  /* ---------- the review deck: [level, question, answer] ---------- */
  D.deck = [
    [1, "Name the four ultimate realities.", "Citta (consciousness), cetasika (mental factors), rūpa (matter) and Nibbāna."],
    [1, "How many kinds of each reality are there?", "89 cittas (121 in detail), 52 cetasikas, 28 kinds of matter, and one Nibbāna."],
    [1, "Which book of the Abhidhamma analyses, and which relates everything by conditions?", "The Dhammasaṅgaṇī analyses; the Paṭṭhāna relates."],
    [1, "What are conventional and ultimate truth called in Pāli?", "Sammuti-sacca and paramattha-sacca."],
    [1, "Name the four parts of a commentarial definition.", "Characteristic, function, manifestation and proximate cause."],
    [1, "In SN 22.95, what are the five aggregates compared to?", "Form to a lump of foam, feeling to a bubble, perception to a mirage, formations to a plantain trunk, consciousness to a magic show."],
    [2, "Name the seven universal mental factors.", "Contact, feeling, perception, volition, one-pointedness, life faculty and attention."],
    [2, "How many cittas are unwholesome, and by which roots?", "Twelve: eight rooted in greed, two in hatred, two in delusion."],
    [2, "In which cittas does mental displeasure (domanassa) occur?", "Only in the two hate-rooted cittas."],
    [2, "What are the four origins of matter?", "Kamma, citta, temperature and nutriment."],
    [2, "Name the eight inseparable kinds of matter.", "Earth, water, fire and air; colour, smell, taste and nutritive essence."],
    [2, "How are the 89 cittas divided by plane?", "54 sense-sphere, 15 fine-material, 12 immaterial and 8 supramundane."],
    [3, "How many mind-moments make a complete five-door process?", "Seventeen, counting the past life-continuum moment."],
    [3, "At which moment of a five-door process does seeing occur?", "The fifth: after past life-continuum, vibration, arrest and five-door adverting."],
    [3, "In which moments is new kamma made?", "In the javanas, usually seven of them."],
    [3, "What happens when the object is only slight?", "The process stops at determining; no javanas run."],
    [3, "Which citta fills the gaps between processes?", "The life-continuum (bhavaṅga), the same resultant citta as rebirth-linking."],
    [3, "What decides whether the javanas are wholesome or unwholesome?", "Wise or unwise attention, at the turning point of determining."],
    [4, "What are the two roots of the wheel of dependent origination?", "Ignorance and craving."],
    [4, "Name the twelve links in order.", "Ignorance, formations, consciousness, mind-and-matter, six bases, contact, feeling, craving, clinging, becoming, birth, ageing-and-death."],
    [4, "Which links belong to the past life in the three-life reading?", "Ignorance and formations."],
    [4, "Which four conditions, the Saṅgaha says, include all 24?", "Object, decisive support, kamma and presence."],
    [4, "Name a condition that holds between things arising at the same time.", "Conascence (sahajāta); also mutuality, support, association and presence."],
    [4, "Where does the wheel turn from present results to present causes?", "Between feeling and craving: the second of its three connections."],
    [5, "What is kamma, strictly speaking?", "Volition (cetanā)."],
    [5, "Name the four kinds of kamma by function.", "Productive, supportive, obstructive and destructive."],
    [5, "Name the four kinds of kamma by order of ripening.", "Weighty, death-proximate, habitual and reserve."],
    [5, "What three kinds of object can appear at the time of death?", "Kamma, a sign of kamma, or a sign of destiny."],
    [5, "How are the 31 planes divided?", "11 sense-sphere, 16 fine-material and 4 immaterial planes."],
    [5, "Which plane has matter but no mind?", "The plane of non-percipient beings."],
    [6, "How many meditation subjects does the Visuddhimagga list?", "Forty."],
    [6, "Name the three signs (nimitta) of concentration.", "The preliminary, learning and counterpart signs."],
    [6, "Name the three stages of concentration.", "Preliminary, access and absorption."],
    [6, "Which subjects can lead to all five jhānas?", "The ten kasiṇas and mindfulness of breathing."],
    [6, "Which three fetters are abandoned at stream-entry?", "Identity view, doubt, and clinging to rites and rituals."],
    [6, "What is the first purification, and the last?", "Purification of virtue; purification by knowledge and vision."],
    [7, "How many elements do the Theravāda, Sarvāstivāda and Yogācāra count?", "82, 75 and 100."],
    [7, "Which thread runs through the most plates?", "Citta, through ten of the fifteen."],
    [7, "Trace the loop of a life on the concept map.", "Kamma → rebirth → life-continuum → process → javana → kamma."],
    [7, "Which idea takes part in the most links on the concept map?", "Citta."],
    [7, "In the moment of seeing a mango and wanting it, which factor leads the javanas?", "Greed (lobha)."],
    [7, "Which of the 17 moments is the mango simile's “eating”?", "The javanas."]
  ];

