  /* ---------- more review cards: [level, question, answer, type: why / classify / relate / apply] ---------- */
  D.deck = D.deck.concat([
    [1, "Why is “chariot” a convention and not a falsehood?", "It rightly names parts assembled in a certain way; only no chariot is found apart from them (Plate 2).", "why"],
    [1, "Which reality do feeling, perception and formations belong to?", "All three are cetasikas: feeling and perception one factor each, formations the other fifty (Plate 2).", "classify"],
    [1, "Which aggregate is the same reality as citta?", "Consciousness (viññāṇa): all 89 cittas (Plate 2).", "relate"],
    [1, "In one moment of seeing a colour, what is the base and what is the object?", "Eye-sensitivity is the base; the colour is the object (Plate 2).", "apply"],
    [1, "Why does Nibbāna belong to no aggregate?", "Every aggregate is conditioned; Nibbāna is unconditioned (Plate 2).", "why"],
    [2, "Classify citta 1 on Plate 3: root, feeling, view, prompting.", "Greed-rooted, with joy, with wrong view, unprompted (Plate 3).", "classify"],
    [2, "Why can displeasure never arise in a wholesome citta?", "It occurs only in the two hate-rooted cittas, which are unwholesome (Plate 3).", "why"],
    [2, "Which two feelings can body-consciousness carry, and when?", "Bodily pleasure when it is wholesome-resultant, bodily pain when unwholesome-resultant (Plate 3).", "classify"],
    [2, "Why do unwholesome and beautiful factors never meet in one citta?", "A citta is either unwholesome or beautiful, never both, and each family arises only in cittas of its own kind (Plate 4).", "why"],
    [2, "Which ten kinds of matter make an eye-decad?", "The eight inseparables, the life faculty and eye-sensitivity (Plate 5).", "apply"],
    [2, "In a five-door process, which job does citta 29 do?", "Determining (Plate 3b).", "relate"],
    [2, "Which cittas can perform rebirth-linking?", "Nineteen: the two investigating cittas with equanimity, the eight great resultants, five fine-material and four immaterial resultants (Plate 3b).", "classify"],
    [3, "In the mango moment, which citta fills moment 5?", "Eye-consciousness, a rootless resultant: citta 20 for a pleasing object (Plates 7, 3).", "apply"],
    [3, "Why does seeing itself make no kamma?", "Eye-consciousness is a resultant; only the javanas make new kamma (Plate 7).", "why"],
    [3, "Why is a five-door process seventeen moments long?", "The object is matter, and a unit of matter lasts seventeen mind-moments (Plates 5, 7).", "relate"],
    [3, "The object is only slight. What happens after determining?", "Determining repeats and the mind sinks back into the life-continuum: no javanas, no kamma (Plate 7).", "apply"],
    [4, "Name two conditions by which the eye-base supports eye-consciousness.", "Prenascence and support; also presence (Plate 8).", "apply"],
    [4, "Why are most conditions not chains of cause and effect?", "Conascent things, like a citta and its factors, support each other in the same moment, like a tripod (Plate 8).", "why"],
    [4, "To which family does postnascence belong?", "Mind → matter: later cittas sustain the body that arose before them (Plate 8).", "classify"],
    [4, "In which phase of Plate 7 do links 8–10 arise?", "In the javanas: craving, clinging and becoming (Plates 7, 9).", "relate"],
    [4, "In which round are links 3–7 of the wheel?", "The round of results (Plate 9).", "classify"],
    [5, "The first javana of a greedy run: when can its kamma ripen?", "Only in this life; otherwise it becomes defunct (Plate 10).", "apply"],
    [5, "What object does rebirth-linking take?", "The same object as the last javanas of the life before: a kamma, a kamma sign or a destiny sign (Plate 10).", "relate"],
    [5, "Devadatta wounded the Buddha. Which kind of kamma by order is that?", "Weighty kamma: a heinous deed (Plate 10; Level V stories).", "classify"],
    [5, "Why do cittas in the immaterial planes need no physical base?", "No matter arises there at all (Plates 11, 3b).", "why"],
    [5, "In which planes does jhāna kamma ripen?", "In the fine-material (Brahmā) and immaterial planes that match the jhāna (Plates 11, 12).", "relate"],
    [6, "Why does loving-kindness stop at the fourth jhāna?", "It comes with pleasant feeling, and the fifth jhāna needs neutral feeling (Plate 12).", "why"],
    [6, "Foulness of a corpse: which temperament, and how deep?", "The lustful; first jhāna only (Plate 12).", "classify"],
    [6, "Purification 4, overcoming doubt, draws on which plates?", "Plates 8–9: discerning the conditions of mind and matter (Plate 13).", "relate"],
    [6, "Sensual desire and ill will are weakened but not cut. Which path?", "Once-return (Plate 13).", "apply"],
    [6, "Why is even the highest immaterial jhāna not liberation?", "It leads to rebirth in an immaterial plane, still within the round; insight is needed for the path (Plates 11–13).", "why"],
    [7, "In the mango moment, which conditions join greed to the javana?", "Root, with the conascent set: conascence, mutuality, support, association, presence, non-disappearance (Plates 8, 14).", "apply"],
    [7, "In the mango moment, which link of the wheel is the wanting?", "Craving, link 8, arising from feeling: the second connection (Plates 9, 14).", "relate"],
    [7, "Why does the Theravāda count 82 elements and the Sarvāstivāda 75?", "They group differently: 52 or 46 factors, 28 or 11 kinds of matter, 14 dissociated formations, one or three unconditioned (Plate 15).", "why"],
    [7, "Read the mango javanas through four lenses: reality, quality, root, kamma.", "Citta with its factors; unwholesome; greed-rooted; kamma that can ripen in this, the next or a later life (Plate 14).", "classify"]
  ]);

  /* ---------- level pages: a check before you start, and hints for the Reflect questions ---------- */
  D.prereq = {"2": [["Name the four ultimate realities.", "Citta, cetasika, rūpa (matter) and Nibbāna (Plate 2)."], ["Which three aggregates are cetasikas?", "Feeling, perception and formations (Plate 2)."], ["Is “a person” false, in the Abhidhamma's view?", "No: it is a true convention, not an ultimate reality (Plate 2)."]], "3": [["What is a resultant citta?", "The ripening of past kamma; it makes no new kamma (Plate 3)."], ["Name two rootless cittas.", "For example eye-consciousness and receiving; also investigating and five-door adverting (Plates 3, 3b)."], ["How long does a unit of matter last?", "Seventeen mind-moments, 51 sub-moments (Plate 5)."]], "4": [["In which moments is new kamma made?", "In the javanas (Plate 7)."], ["What supports eye-consciousness from the side of matter?", "The eye-base and the visible object (Plates 2, 7)."], ["Do a citta and its factors arise one after another?", "No: together, with one object and one base (Plate 4)."]], "5": [["What is the life-continuum?", "The resultant citta, of the same kind as rebirth-linking, that runs between processes (Plates 3b, 7)."], ["Which links of the wheel are kamma?", "Formations (link 2) and the kamma side of becoming (link 10) (Plate 9)."], ["Which link of the wheel begins with rebirth-linking?", "Link 3, consciousness (Plate 9)."]], "6": [["What does “defining mind and matter” cover?", "Citta and cetasikas as mind, the 28 kinds of matter as matter (Plates 2–5)."], ["How many fine-material jhānas does the Abhidhamma count?", "Five (Plate 3)."], ["What are the two roots of the wheel?", "Ignorance and craving (Plate 9)."]], "7": [["At which moments of seeing a mango does the wanting arise?", "In the javanas, moments 9–15 (Plate 7)."], ["Which condition does greed give the javana?", "Root condition, with conascence (Plate 8)."], ["Which path ends sensual desire?", "Non-return (Plate 13)."]]};
  D.hints = {"1": ["Ask what you could no longer say truly, or do, if every use of “chariot” were a lie; Vajirā's reply on the Level I story page frames it.", "Open contact's card on the identity-card page and ask which of its four parts tells you how to recognise contact in your own day."], "2": ["If displeasure never arises without hatred, look at what is present in every moment of grief; Kisāgotamī's story on the Level II story page reads it this way.", "Check where feeling sits on Plate 4's innermost ring, then ask what “neutral” means on Plate 3."], "3": ["Look at what comes after seeing on Plate 7, and at what decides the javanas in Makhādeva's story and on Plate 7b.", "Count how many of the object's seventeen moments are left by the time a weak object is noticed (Plate 7, “Why seventeen?”)."], "4": ["Plate 8 says many conditions work at the same moment, so ask whether the list's order shows time or which supports which.", "Notice what you are thinking about when you think “my teacher” or “a chariot” (Plates 2 and 8)."], "5": ["Lay Plate 10's hinge under Plate 7's strip and ask which part of a process the dying process shares, and what follows it.", "Ask which kind of kamma is most likely to be at hand at death when there is no weighty kamma, then read Maṭṭhakuṇḍalī and Mallikā on the Level V story page."], "6": ["Read the small labels under purifications 3 and 4 on Plate 13's trunk.", "Ask what a trunk could do without roots, and what insight needs from a steady mind; the rose-apple story on the Level VI story page is a clue."], "7": ["Start from Plate 15's “Time” box, then look for the plates built on momentariness, such as 5, 7 and 10.", "Compare the concept map's arrows with Plate 8's 24 conditions: which one tells you how one thing supports another, and which tells you where to look next?"]};

